H.background();
const w = H.W, h = H.H;
// Photon energy E = h f.  Slider gives frequency in units of 10^14 Hz.
const f14 = P.freq;                  // x10^14 Hz
const f = f14 * 1e14;                // Hz
const hSI = 6.626e-34;               // J*s
const h_eV = 4.136e-15;              // eV*s
const c = 3.0e8;                     // m/s
const E_J = hSI * f;                 // joules
const E_eV = h_eV * f;               // eV
const lambda_nm = (c / f) * 1e9;     // wavelength in nm
// approximate visible color from wavelength for the wave stroke
function waveColor(nm) {
  if (nm < 400) return H.colors.violet;
  if (nm < 450) return "#8a7bff";
  if (nm < 490) return "#5aa9ff";
  if (nm < 560) return H.colors.good;
  if (nm < 590) return H.colors.yellow;
  if (nm < 635) return H.colors.accent2;
  if (nm < 700) return H.colors.warn;
  return "#b85a5a";
}
const col = waveColor(lambda_nm);
// a propagating EM wave across the SAME window; more wiggles when f is higher
const y0 = h * 0.46;
const wavesShown = H.clamp(f14 * 0.6, 1, 10);   // spatial cycles across the box
const pts = [];
const x1 = 40, x2 = w - 40;
for (let i = 0; i <= 300; i++) {
  const xx = H.lerp(x1, x2, i / 300);
  const phase = (i / 300) * H.TAU * wavesShown - t * 4;
  const yy = y0 + 70 * Math.sin(phase);
  pts.push([xx, yy]);
}
H.path(pts, { color: col, width: 3 });
H.line(x1, y0, x2, y0, { color: H.colors.grid, width: 1, dash: [4, 4] });
// a marching photon dot riding the wave (loops across the window)
const ride = (t * 0.18) % 1;
const rx = H.lerp(x1, x2, ride);
const rPhase = ride * H.TAU * wavesShown - t * 4;
H.circle(rx, y0 + 70 * Math.sin(rPhase), 6, { fill: H.colors.ink });
// energy bar that grows with E (E proportional to f)
const barMax = h * 0.20;
const barH = H.clamp(E_eV / 4, 0, 1) * barMax;   // 0..4 eV maps to full bar
H.rect(w - 60, y0 + 110 - barH, 26, barH, { fill: col, stroke: H.colors.axis, width: 1, radius: 3 });
H.text("E", w - 52, y0 + 128, { color: H.colors.sub, size: 12 });
// title + readouts
H.text("Photon energy:  E = h · f", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + f14.toFixed(2) + " ×10¹⁴ Hz    λ = c/f = " + lambda_nm.toFixed(0) + " nm", 24, 56, { color: H.colors.sub, size: 13 });
H.text("E = h·f = " + E_eV.toFixed(2) + " eV", 24, 78, { color: col, size: 14, weight: 700 });
H.text("   = " + E_J.toExponential(2) + " J   (h = 6.63×10⁻³⁴ J·s)", 24, 98, { color: H.colors.sub, size: 13 });
H.text("higher frequency → shorter λ → MORE energy per photon", 24, h - 18, { color: H.colors.sub, size: 12 });
